/* MAZESCRN.S wep_fx: `wep_sfx` = PlacedEf into reserved voice 1;
 * xwep_fx (cocking, "noise on another channel"): ordinary `sfx`. */
case AVP_WC_SOUND:
    wepfxID=avp_music_placed_voice(weapon_sfx_descriptor(c->a),1u);
    break;
case AVP_WC_SOUND_ALT:
